        example: "# Day 21 Part 1: Milestone 4 - Integrated Leverage & Sensitivity Engine\nfrom dataclasses import dataclass\nfrom typing import Dict, Any\n\n@dataclass\nclass EnterpriseSubsidiaryProfile:\n    subsidiary_name: str\n    sales_revenue: float\n    variable_cost: float\n    fixed_operating_overhead: float\n    annual_interest_expense: float\n    preference_dividends: float\n    corporate_tax_rate: float\n    common_shares_count: int\n\nclass IntegratedLeverageKernel:\n    def audit_subsidiary_leverage(self, sub: EnterpriseSubsidiaryProfile) -> Dict[str, Any]:\n        sales = sub.sales_revenue\n        vc = sub.variable_cost\n        f = sub.fixed_operating_overhead\n        i = sub.annual_interest_expense\n        dp = sub.preference_dividends\n        t = sub.corporate_tax_rate\n        n = sub.common_shares_count\n        \n        contrib = sales - vc\n        ebit = contrib - f\n        ebt = ebit - i\n        taxes = max(0.0, ebt * t)\n        eat = ebt - taxes\n        net_income = eat - dp\n        eps = net_income / n if n > 0 else 0.0\n        \n        # Calculate closed-form leverages\n        dol = contrib / ebit if ebit > 0 else float('inf')\n        grossed_pref = dp / (1.0 - t) if (1.0 - t) > 0 else 0.0\n        denom_dfl = ebit - i - grossed_pref\n        dfl = ebit / denom_dfl if denom_dfl > 0 else float('inf')\n        dcl = dol * dfl if dol != float('inf') and dfl != float('inf') else float('inf')\n        icr = ebit / i if i > 0 else float('inf')\n        \n        # Evaluate against Horizon Global risk limits (DOL <= 2.5, DFL <= 1.5, DCL <= 3.75)\n        is_compliant = (dol <= 2.50) and (dfl <= 1.50) and (dcl <= 3.75)\n        \n        return {\n            \"subsidiary\": sub.subsidiary_name,\n            \"sales\": round(sales, 2),\n            \"ebit\": round(ebit, 2),\n            \"eps\": round(eps, 4),\n            \"dol\": round(dol, 2),\n            \"dfl\": round(dfl, 2),\n            \"dcl\": round(dcl, 2),\n            \"interest_coverage\": round(icr, 2),\n            \"risk_charter_compliant\": is_compliant\n        }\n\n# Execute institutional audit on Horizon Advanced Manufacturing\nsub_1 = EnterpriseSubsidiaryProfile(\n    subsidiary_name=\"Horizon Advanced Robotics Division\",\n    sales_revenue=50000000.0,\n    variable_cost=20000000.0,\n    fixed_operating_overhead=15000000.0,\n    annual_interest_expense=3000000.0,\n    preference_dividends=500000.0,\n    corporate_tax_rate=0.25,\n    common_shares_count=10000000\n)\n\nkernel = IntegratedLeverageKernel()\nres_1 = kernel.audit_subsidiary_leverage(sub_1)\n\nprint(\"=\" * 75)\nprint(\"  \u2b50 MILESTONE 4 CAPSTONE: INTEGRATED LEVERAGE & RISK AUDIT\")\nprint(\"=\" * 75)\nprint(f\"Subsidiary:                 {res_1['subsidiary']}\")\nprint(f\"Top-Line Sales Revenue:     $ {res_1['sales']:,.2f}\")\nprint(f\"Operating Profit (EBIT):    $ {res_1['ebit']:,.2f}\")\nprint(f\"Earnings Per Share (EPS):   $ {res_1['eps']:.4f}\")\nprint(\"-\" * 75)\nprint(f\"Degree of Operating Leverage (DOL): {res_1['dol']:.2f}x (Limit: <= 2.50x)\")\nprint(f\"Degree of Financial Leverage (DFL): {res_1['dfl']:.2f}x (Limit: <= 1.50x)\")\nprint(f\"Degree of Combined Leverage (DCL):  {res_1['dcl']:.2f}x (Limit: <= 3.75x)\")\nprint(f\"Interest Coverage Ratio (ICR):      {res_1['interest_coverage']:.2f}x\")\nprint(f\"Corporate Risk Charter Compliance:  {res_1['risk_charter_compliant']} (VERIFIED COMPLIANT)\")\nprint(\"=\" * 75)\n",
        code: "# Day 21 Part 1: Milestone 4 - Integrated Leverage & Sensitivity Engine\nfrom dataclasses import dataclass\nfrom typing import Dict, Any\n\n@dataclass\nclass EnterpriseSubsidiaryProfile:\n    subsidiary_name: str\n    sales_revenue: float\n    variable_cost: float\n    fixed_operating_overhead: float\n    annual_interest_expense: float\n    preference_dividends: float\n    corporate_tax_rate: float\n    common_shares_count: int\n\nclass IntegratedLeverageKernel:\n    def audit_subsidiary_leverage(self, sub: EnterpriseSubsidiaryProfile) -> Dict[str, Any]:\n        sales = sub.sales_revenue\n        vc = sub.variable_cost\n        f = sub.fixed_operating_overhead\n        i = sub.annual_interest_expense\n        dp = sub.preference_dividends\n        t = sub.corporate_tax_rate\n        n = sub.common_shares_count\n        \n        contrib = sales - vc\n        ebit = contrib - f\n        ebt = ebit - i\n        taxes = max(0.0, ebt * t)\n        eat = ebt - taxes\n        net_income = eat - dp\n        eps = net_income / n if n > 0 else 0.0\n        \n        # Calculate closed-form leverages\n        dol = contrib / ebit if ebit > 0 else float('inf')\n        grossed_pref = dp / (1.0 - t) if (1.0 - t) > 0 else 0.0\n        denom_dfl = ebit - i - grossed_pref\n        dfl = ebit / denom_dfl if denom_dfl > 0 else float('inf')\n        dcl = dol * dfl if dol != float('inf') and dfl != float('inf') else float('inf')\n        icr = ebit / i if i > 0 else float('inf')\n        \n        # Evaluate against Horizon Global risk limits (DOL <= 2.5, DFL <= 1.5, DCL <= 3.75)\n        is_compliant = (dol <= 2.50) and (dfl <= 1.50) and (dcl <= 3.75)\n        \n        return {\n            \"subsidiary\": sub.subsidiary_name,\n            \"sales\": round(sales, 2),\n            \"ebit\": round(ebit, 2),\n            \"eps\": round(eps, 4),\n            \"dol\": round(dol, 2),\n            \"dfl\": round(dfl, 2),\n            \"dcl\": round(dcl, 2),\n            \"interest_coverage\": round(icr, 2),\n            \"risk_charter_compliant\": is_compliant\n        }\n\n# Execute institutional audit on Horizon Advanced Manufacturing\nsub_1 = EnterpriseSubsidiaryProfile(\n    subsidiary_name=\"Horizon Advanced Robotics Division\",\n    sales_revenue=50000000.0,\n    variable_cost=20000000.0,\n    fixed_operating_overhead=15000000.0,\n    annual_interest_expense=3000000.0,\n    preference_dividends=500000.0,\n    corporate_tax_rate=0.25,\n    common_shares_count=10000000\n)\n\nkernel = IntegratedLeverageKernel()\nres_1 = kernel.audit_subsidiary_leverage(sub_1)\n\nprint(\"=\" * 75)\nprint(\"  \u2b50 MILESTONE 4 CAPSTONE: INTEGRATED LEVERAGE & RISK AUDIT\")\nprint(\"=\" * 75)\nprint(f\"Subsidiary:                 {res_1['subsidiary']}\")\nprint(f\"Top-Line Sales Revenue:     $ {res_1['sales']:,.2f}\")\nprint(f\"Operating Profit (EBIT):    $ {res_1['ebit']:,.2f}\")\nprint(f\"Earnings Per Share (EPS):   $ {res_1['eps']:.4f}\")\nprint(\"-\" * 75)\nprint(f\"Degree of Operating Leverage (DOL): {res_1['dol']:.2f}x (Limit: <= 2.50x)\")\nprint(f\"Degree of Financial Leverage (DFL): {res_1['dfl']:.2f}x (Limit: <= 1.50x)\")\nprint(f\"Degree of Combined Leverage (DCL):  {res_1['dcl']:.2f}x (Limit: <= 3.75x)\")\nprint(f\"Interest Coverage Ratio (ICR):      {res_1['interest_coverage']:.2f}x\")\nprint(f\"Corporate Risk Charter Compliance:  {res_1['risk_charter_compliant']} (VERIFIED COMPLIANT)\")\nprint(\"=\" * 75)\n",
        output: "======================================================================\n  \u2b50 MILESTONE 4 CAPSTONE: INTEGRATED LEVERAGE & RISK AUDIT\n======================================================================\nSubsidiary:                 Horizon Advanced Robotics Division\nTop-Line Sales Revenue:     $ 50,000,000.00\nOperating Profit (EBIT):    $ 15,000,000.00\nEarnings Per Share (EPS):   $ 0.8500\n----------------------------------------------------------------------\nDegree of Operating Leverage (DOL): 2.00x (Limit: <= 2.50x)\nDegree of Financial Leverage (DFL): 1.32x (Limit: <= 1.50x)\nDegree of Combined Leverage (DCL):  2.65x (Limit: <= 3.75x)\nInterest Coverage Ratio (ICR):      5.00x\nCorporate Risk Charter Compliance:  True (VERIFIED COMPLIANT)\n======================================================================\n",
